{#- Covering letter to the AD bank for lodging export documents (Shipping Bill).
    Collection under DP / DA, negotiation under LC, or regularisation of an advance received.
    The enclosures are the shipment checklist's documents that are ready. -#}
{%- import "india_exim/templates/print_formats/exim_macros.html" as exim -%}
{%- set ad = frappe.db.get_value("Port AD Code", {"parenttype": "Port Master", "parent": doc.port_code, "company": doc.company, "ad_code": doc.ad_code}, ["bank", "bank_account"], as_dict=True) if doc.ad_code else frappe.db.get_value("Port AD Code", {"parenttype": "Port Master", "company": doc.company}, ["bank", "bank_account"], as_dict=True, order_by="is_default desc") -%}
{%- set bank_account = (ad.bank_account if ad else None) or frappe.db.get_value("Bank Account", {"company": doc.company, "is_company_account": 1, "is_default": 1, "disabled": 0}) -%}
{%- set bank = (ad.bank if ad else None) or (frappe.db.get_value("Bank Account", bank_account, "bank") if bank_account else None) -%}
{%- set shipment = frappe.get_doc("Export Shipment", doc.export_shipment) if doc.export_shipment else None -%}
{%- set invoices = [] -%}
{%- for row in doc.items if row.sales_invoice and row.sales_invoice not in invoices %}{% set _ = invoices.append(row.sales_invoice) %}{% endfor -%}
{%- set first = frappe.get_doc("Sales Invoice", invoices[0]) if invoices else None -%}
{%- set terms = (first.get("exim_payment_terms_type") if first else None) or (shipment.payment_terms_type if shipment else "") or "" -%}
{%- if terms == "Letter of Credit" -%}{%- set purpose = _("negotiation under the Letter of Credit") -%}
{%- elif terms == "Advance" -%}{%- set purpose = _("regularisation against the advance remittance already received") -%}
{%- elif "Acceptance" in terms -%}{%- set purpose = _("collection on Documents against Acceptance (DA) basis") -%}
{%- elif terms == "Open Account" -%}{%- set purpose = _("collection on open account terms") -%}
{%- elif not terms -%}{%- set purpose = _("collection") -%}
{%- else -%}{%- set purpose = _("collection on Documents against Payment (DP) basis") -%}{%- endif -%}
{{ exim.style() }}
<div class="exim letter">
	<table class="plain">
		<tr>
			<td style="width: 60%"><b>{{ doc.company }}</b><br>
				{%- set iec = exim.company_iec(doc.company) %}{% if iec %}{{ _("IEC") }}: {{ iec }}<br>{% endif %}
				{% if doc.ad_code %}{{ _("AD Code") }}: {{ doc.ad_code }}{% endif %}</td>
			<td class="num">{{ _("Date") }}: {{ exim.date(frappe.utils.today()) }}<br>{{ _("Our Ref.") }}: {{ doc.name }}</td>
		</tr>
	</table>
	<p class="gap">{{ _("To") }},<br>{{ _("The Manager, Trade Finance / Export Department") }}<br><b>{{ bank or "__________________" }}</b></p>
	<p><b>{{ _("Sub: Lodgement of export documents for {0}").format(purpose) }}</b></p>
	<p>{{ _("Dear Sir / Madam,") }}</p>
	{%- set account_no = (" " ~ frappe.db.get_value("Bank Account", bank_account, "bank_account_no")) if bank_account else "" %}
	{%- if terms == "Advance" %}
	<p>{{ _("We enclose the following export documents for {0}. Please adjust this shipping bill against the advance credited to our account{1} and close it in EDPMS.").format(purpose, account_no) }}</p>
	{%- else %}
	<p>{{ _("We enclose the following export documents for {0}. Please send them to the buyer's bank and credit the proceeds to our account{1}.").format(purpose, account_no) }}</p>
	{%- endif %}

	<table class="gap">
		<tr>{{ exim.cell(_("Shipping Bill No. & Date"), (doc.shipping_bill_number or "") ~ " / " ~ exim.date(doc.shipping_bill_date)) }}{{ exim.cell(_("Port"), doc.port_code ~ (" - " ~ doc.port_name if doc.port_name else "")) }}</tr>
		<tr>{{ exim.cell(_("Invoice No(s)."), invoices | join(", ")) }}{{ exim.cell(_("Invoice Value"), exim.money(doc.total_invoice_value, doc.currency) ~ " (" ~ _("FOB") ~ " " ~ exim.money(doc.total_fob_value, doc.currency) ~ ")") }}</tr>
		<tr>{{ exim.cell(_("Drawee / Buyer"), doc.customer_name ~ (", " ~ doc.destination_country if doc.destination_country else "")) }}{{ exim.cell(_("Payment Terms"), terms ~ ((" — " ~ _("LC No.") ~ " " ~ first.exim_lc_number) if first and first.get("exim_lc_number") else "")) }}</tr>
		<tr>{{ exim.cell(_("LEO Date"), exim.date(doc.leo_date)) }}{{ exim.cell(_("Realisation Due By"), exim.date(doc.realisation_due_date)) }}</tr>
		{%- set bl_number = doc.bl_number or (shipment.bl_number if shipment else None) %}
		{%- set bl_date = doc.bl_date or (shipment.bl_date if shipment else None) %}
		{%- if bl_number %}
		<tr>{{ exim.cell(_("Transport Document"), ((shipment.bl_type if shipment else None) or _("BL / AWB")) ~ " " ~ bl_number ~ " / " ~ exim.date(bl_date)) }}{{ exim.cell(_("Vessel / Voyage"), shipment.vessel_voyage if shipment else "") }}</tr>
		{%- endif %}
	</table>

	<table class="gap">
		<thead><tr><th style="width: 6%">{{ _("Sr.") }}</th><th>{{ _("Document Enclosed") }}</th><th style="width: 22%">{{ _("No. / Date") }}</th><th class="num" style="width: 12%">{{ _("Originals") }}</th></tr></thead>
		<tbody>
		{%- set enclosed = (shipment.documents | selectattr("status", "in", ["Received", "Checked", "Sent", "Accepted"]) | list) if shipment else [] %}
		{%- for row in enclosed %}
			<tr><td>{{ loop.index }}</td><td>{{ row.document_type }}</td><td>{{ row.document_number or "" }}{% if row.document_date %} / {{ exim.date(row.document_date) }}{% endif %}</td><td class="num">{{ row.originals_required or "" }}</td></tr>
		{%- else %}
			<tr><td>1</td><td>{{ _("Commercial Invoice") }}</td><td>{{ invoices | join(", ") }}</td><td></td></tr>
			<tr><td>2</td><td>{{ _("Packing List") }}</td><td></td><td></td></tr>
			<tr><td>3</td><td>{{ _("Transport Document (Bill of Lading / Air Waybill)") }}</td><td>{{ bl_number or "" }}{% if bl_date %} / {{ exim.date(bl_date) }}{% endif %}</td><td></td></tr>
			<tr><td>4</td><td>{{ _("Bill of Exchange") }}</td><td></td><td></td></tr>
			<tr><td>5</td><td>{{ _("Copy of Shipping Bill") }}</td><td>{{ doc.shipping_bill_number or "" }}</td><td></td></tr>
		{%- endfor %}
		</tbody>
	</table>

	<p class="gap">{{ _("Instructions:") }}</p>
	<p>{% if terms not in ("Advance", "Open Account", "") %}1. {{ _("Deliver the documents against {0}.").format(_("acceptance of the bill of exchange") if "Acceptance" in terms else _("payment")) }}{% endif %}
	2. {{ _("Your charges and the foreign bank's charges are to the account of the drawee, unless stated otherwise.") }}
	3. {{ _("Please report the shipping bill in EDPMS and issue the e-BRC once the proceeds are realised.") }}</p>
	<p>{{ _("We declare that the documents are genuine and that the goods have been exported as stated in the shipping bill, in line with FEMA and the RBI's directions on export of goods.") }}</p>
	<p>{{ _("Yours faithfully,") }}</p>
	{{ exim.signature(doc.company) }}
</div>
